(function(){
  var C={"segments": [{"label": "โดยตรง", "value": 8, "color": "#e5484d", "label_en": "Direct"}, {"label": "โปรโมชัน", "value": 1, "color": "#8b5cf6", "label_en": "Promotions"}, {"label": "อัตโนมัติ (~100)", "value": 100, "color": "#2f9e6b", "display": "~100", "label_en": ""}, {"label": "ที่เหลือ ทีมบัญชี/อื่นๆ (~41)", "value": 41, "color": "#3b6cf6", "display": "~41", "label_en": ""}], "cv": "~150", "cl": "ฉบับ", "cle": "emails"};
  var segs=C.segments;
  if(segs.length){
    var total=segs.reduce(function(a,d){return a+d.value},0),r=70,L=2*Math.PI*r,off=0,svg='';
    segs.forEach(function(d){var len=d.value/total*L;
      svg+='<circle cx="100" cy="100" r="'+r+'" fill="none" stroke="'+d.color+'" stroke-width="32" stroke-dasharray="'+len+' '+(L-len)+'" stroke-dashoffset="'+(-off)+'" transform="rotate(-90 100 100)"/>';off+=len;});
    svg+='<text x="100" y="102" text-anchor="middle" font-size="24" font-weight="700">'+C.cv+'</text><text class="sub th" x="100" y="124" text-anchor="middle" font-size="12">'+C.cl+'</text><text class="sub en" x="100" y="124" text-anchor="middle" font-size="12">'+(C.cle||C.cl)+'</text>';
    document.getElementById('donut').innerHTML=svg;
    document.getElementById('legend').innerHTML=segs.map(function(d){return '<div><span class="dot" style="background:'+d.color+'"></span>'+'<span class="th">'+d.label+'</span><span class="en">'+(d.label_en||d.label)+'</span>: <b>'+(d.display||d.value)+'</b></div>'}).join('');
  }
  var btns=root.querySelectorAll('.filters button'),groups=root.querySelectorAll('.group');
  btns.forEach(function(b){b.addEventListener('click',function(){
    btns.forEach(function(x){x.classList.remove('active')});b.classList.add('active');
    var f=b.dataset.f;groups.forEach(function(g){g.style.display=(f==='all'||g.dataset.g===f)?'':'none'});
  })});
})();


